    "prov:action": "#########\n# GDSC ETL is performed in two steps: shell script to ETL data into postgres\n# and then additional transformations with SQL in postGIS (if needed).\n####\n\n#########\n# Step 1 - bash script (pseudo code)\n####\n\n# create directory structure and move into it\nmkdir -p /data/us_2014_2019_monthly_pm25_by_county_cdc/download -p /data/us_2014_2019_monthly_pm25_by_county_cdc/etl\nchmod -R 777 /data/us_2014_2019_monthly_pm25_by_county_cdc\ncd /data/us_2014_2019_monthly_pm25_by_county_cdc\n\n# set update flag based on last update and update frequency\ndo_update=0 if date() < last_update + update_frequency else do_update = 1\n\n# load us_2019_county_tl as dependency (see us_2019_county_tl for details).\n\n# download if update flag is set:\nif do_update == 1 then\nwget --retry-connrefused --waitretry=1 --read-timeout=20 --timeout=15 -t 10 -O download/us_2014_2019_monthly_pm25_by_county_cdc.csv 'https://data.cdc.gov/api/v3/views/53mz-4zqd/query.csv?query=SELECT%0A%20%20%60year%60%2C%0A%20%20%60date%60%2C%0A%20%20%60statefips%60%2C%0A%20%20%60countyfips%60%2C%0A%20%20%60pm25_max_pred%60%2C%0A%20%20%60pm25_med_pred%60%2C%0A%20%20%60pm25_mean_pred%60%2C%0A%20%20%60pm25_pop_pred%60%0AWHERE%0A%20%20caseless_one_of(%60year%60%2C%20%222014%22%2C%20%222015%22%2C%20%222016%22%2C%20%222017%22%2C%20%222018%22%2C%20%222019%22)&app_token='\"$CDC_APP_TOKEN\"'' 2>&1\n\n# remove spaces, periods, and leading numerical digits in column headers (if needed)\n  if (head -n 1 download/us_2014_2019_monthly_pm25_by_county_cdc.csv | grep -qE '\\s|\\.|\\\"[0-9]'); then\n    sed -i '1s/ /_/g; 1s/\\.//g; 1s/\\\"\\([0-9]\\)/\\\"n\\1/g' download/us_2014_2019_monthly_pm25_by_county_cdc.csv 2>&1\n  fi\n\n# load into postGIS with:\nogr2ogr -lco GEOMETRY_NAME=geom -f PostgreSQL PG:\"<postgres connection>\" download/us_2014_2019_monthly_pm25_by_county_cdc.csv -dialect sqlite -sql \"WITH all_rows AS (SELECT year, DATE(SUBSTR(date, 6) || '-' || CASE SUBSTR(date, 3, 3) WHEN 'JAN' THEN '01' WHEN 'FEB' THEN '02' WHEN 'MAR' THEN '03' WHEN 'APR' THEN '04' WHEN 'MAY' THEN '05' WHEN 'JUN' THEN '06' WHEN 'JUL' THEN '07' WHEN 'AUG' THEN '08' WHEN 'SEP' THEN '09' WHEN 'OCT' THEN '10' WHEN 'NOV' THEN '11' WHEN 'DEC' THEN '12' END || '-01') AS start_date, FORMAT('%02d', statefips) AS statefips, FORMAT('%03d', countyfips) AS countyfips, MAX(CAST(pm25_max_pred AS decimal)) AS pm25_max_pred, MEDIAN(CAST(pm25_med_pred AS decimal)) AS pm25_med_pred, AVG(CAST(pm25_mean_pred AS decimal)) AS pm25_mean_pred, AVG(CAST(pm25_pop_pred AS decimal)) AS pm25_pop_pred FROM us_2014_2019_monthly_pm25_by_county_cdc WHERE pm25_max_pred != '' AND pm25_med_pred != '' AND pm25_mean_pred != '' AND pm25_pop_pred != '' GROUP BY statefips, countyfips, start_date) SELECT statefips, countyfips, statefips || countyfips as geoid, JSON_GROUP_OBJECT(start_date || '/' || DATE(start_date, '+1 month', '-1 day'), pm25_max_pred) AS pm25_max_pred, JSON_GROUP_OBJECT(start_date || '/' || DATE(start_date, '+1 month', '-1 day'), pm25_med_pred) AS pm25_med_pred, JSON_GROUP_OBJECT(start_date || '/' || DATE(start_date, '+1 month', '-1 day'), pm25_mean_pred) AS pm25_mean_pred, JSON_GROUP_OBJECT(start_date || '/' || DATE(start_date, '+1 month', '-1 day'), pm25_pop_pred) AS pm25_pop_pred FROM all_rows GROUP BY statefips, countyfips\" -lco COLUMN_TYPES=\"pm25_mean_pred=jsonb,pm25_med_pred=jsonb,pm25_max_pred=jsonb,pm25_pop_pred=jsonb\" -nlt multipolygon -nln us_2014_2019_monthly_pm25_by_county_cdc\necho success: us_2014_2019_monthly_pm25_by_county_cdc.csv loaded with ogr2ogr\n\n\n#########\n# Step 2 - SQL script (pseudo code):\n####\n\n# remove duplicate points and make geometries valid:\nUPDATE us_2014_2019_monthly_pm25_by_county_cdc\n  SET geom=ST_MakeValid(ST_RemoveRepeatedPoints(geom));\n\n# add local geometry column and reproject existing geometries into local EPSG:\nALTER TABLE us_2014_2019_monthly_pm25_by_county_cdc DROP COLUMN IF EXISTS geom_local CASCADE;\nSELECT AddGeometryColumn (\n  'us_2014_2019_monthly_pm25_by_county_cdc',\n  'geom_local', 4269, 'multipolygon', 2\n);\nUPDATE us_2014_2019_monthly_pm25_by_county_cdc\n  SET geom_local=ST_MakeValid(ST_RemoveRepeatedPoints(ST_Transform(ST_Multi(geom),4269)));\nCREATE INDEX us_2014_2019_monthly_pm25_by_county_cdc_geom_local_idx\n  ON us_2014_2019_monthly_pm25_by_county_cdc\n  USING GIST (geom_local);\nNOTIFY pgrst, 'reload schema';\n-- join temp to us_2014_2019_monthly_pm25_by_county_cdc (column)\nALTER TABLE us_2014_2019_monthly_pm25_by_county_cdc\n  ADD COLUMN IF NOT EXISTS pm25_max_pred jsonb,\n  ADD COLUMN IF NOT EXISTS pm25_med_pred jsonb,\n  ADD COLUMN IF NOT EXISTS pm25_mean_pred jsonb,\n  ADD COLUMN IF NOT EXISTS pm25_pop_pred jsonb;\nUPDATE us_2014_2019_monthly_pm25_by_county_cdc \nSET\n  pm25_max_pred = temp.pm25_max_pred::jsonb,\n  pm25_med_pred = temp.pm25_med_pred::jsonb,\n  pm25_mean_pred = temp.pm25_mean_pred::jsonb,\n  pm25_pop_pred = temp.pm25_pop_pred::jsonb\nFROM temp\nWHERE us_2014_2019_monthly_pm25_by_county_cdc.geoid = temp.geoid;\n\n\n-- remove temporary table\nDROP TABLE temp CASCADE;\n\"\n\n# Move into corrrect directory and create derivative directory in data package on osgeo\ncd /data/us_2014_2019_monthly_pm25_by_county_cdc/\nmkdir -p derived\n\n# Create gpkg of table in derivate directory on osgeo \nrm -f derived/us_2014_2019_monthly_pm25_by_county_cdc.gpkg\nogr2ogr -f GPKG -overwrite derived/us_2014_2019_monthly_pm25_by_county_cdc.gpkg PG:\"<postgres connection>\" -select \"state_fips,countyfips,geoid,pm25_max_pred,pm25_med_pred,pm25_mean_pred,pm25_pop_pred,geom\" us_2014_2019_monthly_pm25_by_county_cdc\n\n# Create downloadable tarfile of gpkg in derivative directory on osgeo\nrm -f derived/us_2014_2019_monthly_pm25_by_county_cdc.gpkg.tar.gz\ntar -czf derived/us_2014_2019_monthly_pm25_by_county_cdc.gpkg.tar.gz meta_dcat_us_2014_2019_monthly_pm25_by_county_cdc.json -C derived us_2014_2019_monthly_pm25_by_county_cdc.gpkg\n\n# Move into correct directory\ncd /data/us_2014_2019_monthly_pm25_by_county_cdc/\n\n# Create pg_dump of table SQL in derivate directory on postgis.\npg_dump <postgres opts> -h gaia-db -t us_2014_2019_monthly_pm25_by_county_cdc > derived/us_2014_2019_monthly_pm25_by_county_cdc.sql\n\n# Create downloadable tarfile of SQL in derivative directory on postgis\nrm -f derived/us_2014_2019_monthly_pm25_by_county_cdc.sql.tar.gz\ntar -czf derived/us_2014_2019_monthly_pm25_by_county_cdc.sql.tar.gz meta_dcat_us_2014_2019_monthly_pm25_by_county_cdc.json -C derived us_2014_2019_monthly_pm25_by_county_cdc.sql\n\n",
