    "prov:action": "#########\n# GDSC ETL is performed in two steps: shell script to ETL data into postgres\n# and then additional transformations with SQL in postGIS (if needed).\n####\n\n#########\n# Step 1 - bash script (pseudo code)\n####\n\n# create directory structure and move into it\nmkdir -p /data/us_2023_annual_aqi_by_county/download -p /data/us_2023_annual_aqi_by_county/etl\nchmod -R 777 /data/us_2023_annual_aqi_by_county\ncd /data/us_2023_annual_aqi_by_county\n\n# set update flag based on last update and update frequency\ndo_update=0 if date() < last_update + update_frequency else do_update = 1\n\n# download if update flag is set:\nif do_update == 1 then\ncurl -o download/us_2023_annual_aqi_by_county.zip 'https://aqs.epa.gov/aqsweb/airdata/annual_aqi_by_county_2023.zip' 2>&1\n\n# unzip to download directory if update flag is set\nif do_update == 1 then\nunzip -o download/us_2023_annual_aqi_by_county.zip -d download && rm download/us_2023_annual_aqi_by_county.zip 2>&1\n\n# remove spaces, periods, and leading numerical digits in column headers (if needed)\n  if (head -n 1 download/annual_aqi_by_county_2023.csv | grep -qE '\\s|\\.|\\\"[0-9]'); then\n    sed -i '1s/ /_/g; 1s/\\.//g; 1s/\\\"\\([0-9]\\)/\\\"n\\1/g' download/annual_aqi_by_county_2023.csv 2>&1\n  fi\n\n# load into postGIS with:\nogr2ogr -lco GEOMETRY_NAME=geom -f PostgreSQL PG:\"<postgres connection>\" download/annual_aqi_by_county_2023.csv -nlt multipolygon -nln us_2023_annual_aqi_by_county\necho success: annual_aqi_by_county_2023.csv loaded with ogr2ogr\n\n# rename data table to temp\npsql -d $POSTGRES_DB -U $POSTGRES_USER -p $POSTGRES_PORT -h gaia-db -c \"\nALTER SEQUENCE IF EXISTS us_2023_annual_aqi_by_county_ogc_fid_seq RENAME TO temp_ogc_fid_seq;\nALTER INDEX IF EXISTS us_2023_annual_aqi_by_county_geom_geom_idx RENAME TO temp_geom_idx;\nALTER TABLE IF EXISTS us_2023_annual_aqi_by_county RENAME CONSTRAINT us_2023_annual_aqi_by_county_pkey TO temp_pkey;\nALTER TABLE us_2023_annual_aqi_by_county RENAME TO temp;\"\n\n# Create copy of geom dependency\npg_dump -d $POSTGRES_DB -U $POSTGRES_USER -p $POSTGRES_PORT -h gaia-db -t us_2023_county_tl | sed 's/us_2023_county_tl/us_2023_annual_aqi_by_county/g' | psql -d $POSTGRES_DB -U $POSTGRES_USER -p $POSTGRES_PORT -h gaia-db\n\n# join as per custom parameters\npsql -d $POSTGRES_DB -U $POSTGRES_USER -p $POSTGRES_PORT -h gaia-db -c \"\nALTER TABLE temp ADD COLUMN geoid varchar;\nUPDATE temp SET geoid = CONCAT(us_2020_census_county_fips.state,us_2020_census_county_fips.county)\n  FROM us_2020_census_county_fips\n  WHERE position(temp.state in us_2020_census_county_fips.state_name)>0\n  AND position(temp.county in us_2020_census_county_fips.county_name)>0;\n\nALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN state varchar;\nUPDATE us_2023_annual_aqi_by_county SET state=temp.state::varchar\n  FROM temp\n  WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;\n\nALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN county varchar;\nUPDATE us_2023_annual_aqi_by_county SET county=temp.county::varchar\n  FROM temp\n  WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;\n\nALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN year varchar;\nUPDATE us_2023_annual_aqi_by_county SET year=temp.year::varchar\n  FROM temp\n  WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;\n\nALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN days_with_aqi int4;\nUPDATE us_2023_annual_aqi_by_county SET days_with_aqi=temp.days_with_aqi::int4\n  FROM temp\n  WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;\n\nALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN good_days int4;\nUPDATE us_2023_annual_aqi_by_county SET good_days=temp.good_days::int4\n  FROM temp\n  WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;\n\nALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN moderate_days int4;\nUPDATE us_2023_annual_aqi_by_county SET moderate_days=temp.moderate_days::int4\n  FROM temp\n  WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;\n\nALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN unhealthy_for_sensitive_groups_days int4;\nUPDATE us_2023_annual_aqi_by_county SET unhealthy_for_sensitive_groups_days=temp.unhealthy_for_sensitive_groups_days::int4\n  FROM temp\n  WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;\n\nALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN unhealthy_days int4;\nUPDATE us_2023_annual_aqi_by_county SET unhealthy_days=temp.unhealthy_days::int4\n  FROM temp\n  WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;\n\nALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN very_unhealthy_days int4;\nUPDATE us_2023_annual_aqi_by_county SET very_unhealthy_days=temp.very_unhealthy_days::int4\n  FROM temp\n  WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;\n\nALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN hazardous_days int4;\nUPDATE us_2023_annual_aqi_by_county SET hazardous_days=temp.hazardous_days::int4\n  FROM temp\n  WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;\n\nALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN max_aqi int4;\nUPDATE us_2023_annual_aqi_by_county SET max_aqi=temp.max_aqi::int4\n  FROM temp\n  WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;\n\nALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN n90th_percentile_aqi int4;\nUPDATE us_2023_annual_aqi_by_county SET n90th_percentile_aqi=temp.n90th_percentile_aqi::int4\n  FROM temp\n  WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;\n\nALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN median_aqi int4;\nUPDATE us_2023_annual_aqi_by_county SET median_aqi=temp.median_aqi::int4\n  FROM temp\n  WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;\n\nALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN days_co int4;\nUPDATE us_2023_annual_aqi_by_county SET days_co=temp.days_co::int4\n  FROM temp\n  WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;\n\nALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN days_no2 int4;\nUPDATE us_2023_annual_aqi_by_county SET days_no2=temp.days_no2::int4\n  FROM temp\n  WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;\n\nALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN days_ozone int4;\nUPDATE us_2023_annual_aqi_by_county SET days_ozone=temp.days_ozone::int4\n  FROM temp\n  WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;\n\nALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN days_pm25 int4;\nUPDATE us_2023_annual_aqi_by_county SET days_pm25=temp.days_pm25::int4\n  FROM temp\n  WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;\n\nALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN days_pm10 int4;\nUPDATE us_2023_annual_aqi_by_county SET days_pm10=temp.days_pm10::int4\n  FROM temp\n  WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;\n\nDROP table temp;\n\"\n",
